/** A quiet day's headline, a sentence to the reader like any other. */
fun quietDayHeadline(culture: AncientCulture): String = when (culture) {
    AncientCulture.EGYPT -> "Do the plain work and call it enough."
    AncientCulture.GREECE -> "You can leave the questions for another day."
    AncientCulture.CANAAN -> "Nobody needs anything from you today."
    AncientCulture.CARTHAGE -> "You owe nothing extra today."
    AncientCulture.ROME -> "Go about your business without looking for signs."
}

/** A quiet day's line: no aspect invented and no reassurance offered. */
fun quietDayLine(culture: AncientCulture): String = when (culture) {
    AncientCulture.EGYPT -> "Nothing on the river runs close enough to weigh. A day of ordinary work, and Ma'at counts it no lower than a feast."
    AncientCulture.GREECE -> "No shrine answers today. The oracle keeps its own counsel, and so should you."
    AncientCulture.CANAAN -> "Not one matter is brought forward today. An ordinary day still stands under El's tent."
    AncientCulture.CARTHAGE -> "The day's page takes no entry. Nothing falls due, and the books close as they opened."
    AncientCulture.ROME -> "Nothing is reported that the augurs would call a sign. The citadel was manned at dawn all the same."
}

/**
