    fun consequence(culture: AncientCulture, aspect: AspectType): String = when (culture) {
        AncientCulture.EGYPT -> when (aspect) {
            AspectType.CONJUNCTION -> "You cannot settle one without the other, because {partner} has tied them together."
            AspectType.SEXTILE -> "Ask once, and {partner} puts a shoulder to your oar."
            AspectType.SQUARE -> "Nothing moves today without {partner} dragging against it."
            AspectType.TRINE -> "What you start today reaches the far bank, and {partner} does not call it back."
            AspectType.OPPOSITION -> "You have to choose a side, and {partner} takes the other one."
        }

        AncientCulture.GREECE -> when (aspect) {
            AspectType.CONJUNCTION -> "Whatever you ask about one, {partner} answers for both."
            AspectType.SEXTILE -> "One plain question opens the way, and {partner} holds the door."
            AspectType.SQUARE -> "The answer you want is not the answer {partner} gives."
            AspectType.TRINE -> "You get a straight answer today, and {partner} gives it without a riddle."
            AspectType.OPPOSITION -> "You will hear two answers, and {partner} speaks the harder one."
        }

        AncientCulture.CANAAN -> when (aspect) {
            AspectType.CONJUNCTION -> "One ruling covers both, and {partner} stands under it with you."
            AspectType.SEXTILE -> "A promise made now holds, and {partner} is its witness."
            AspectType.SQUARE -> "Someone objects to you today, and {partner} gives them the floor."
            AspectType.TRINE -> "What you ask for passes, and {partner} raises no hand against it."
