        }

        AncientCulture.CARTHAGE -> when (aspect) {
            AspectType.CONJUNCTION -> "Pay one and you have paid both, and {partner} holds the receipt."
            AspectType.SEXTILE -> "A small loan made today comes back, and {partner} guarantees it."
            AspectType.SQUARE -> "Someone changes the terms on you today, and {partner} backs them."
            AspectType.TRINE -> "Your figures come out right today, and {partner} initials the total."
            AspectType.OPPOSITION -> "Something has to be paid out today, and {partner} decides what."
        }

        AncientCulture.ROME -> when (aspect) {
            AspectType.CONJUNCTION -> "You answer for both today, and {partner} holds you to it."
            AspectType.SEXTILE -> "One favor asked today is granted, and {partner} remembers who asked."
            AspectType.SQUARE -> "Your business is put off, and {partner} is the reason."
