            AspectType.CONJUNCTION -> "Bring everything about {domain} to {god} at once, and have the scribe write it on one sheet."
            AspectType.SEXTILE -> "Tend to {domain} before noon, and say {god}'s name over the bread."
            AspectType.SQUARE -> "Put {domain} on the scale twice before you act, and let {god} watch."
            AspectType.TRINE -> "Trust {domain} to the current today, and call on {god} as the barge casts off."
            AspectType.OPPOSITION -> "Keep {domain} on your own bank, and hail {god} from there."
        }

        AncientCulture.GREECE -> when (aspect) {
            AspectType.CONJUNCTION -> "Carry one question about {domain} up the road, and put it to {god} in plain words."
            AspectType.SEXTILE -> "Ask about {domain} in the fewest words, and thank {god} before you go down."
            AspectType.SQUARE -> "Hear what {god} says about {domain}, then follow it or go home."
            AspectType.TRINE -> "Spend your morning on {domain}, and pour a little wine for {god} at noon."
            AspectType.OPPOSITION -> "Ask about {domain} from the other side, and let {god} hear both."
        }

        AncientCulture.CANAAN -> when (aspect) {
            AspectType.CONJUNCTION -> "Bring {domain} to the temple court as one pledge, and let {god} hear it."
            AspectType.SEXTILE -> "Ask for help with {domain} in {god}'s hearing."
            AspectType.SQUARE -> "Write down every word said about {domain}, and let {god} keep the tablet."
            AspectType.TRINE -> "Take {domain} to the threshing floor today, and leave a share for {god}."
            AspectType.OPPOSITION -> "Hold {domain} back at the gate until {god} has sat down."
        }

        AncientCulture.CARTHAGE -> when (aspect) {
            AspectType.CONJUNCTION -> "Enter {domain} under one heading today, and seal the page in {god}'s name."
            AspectType.SEXTILE -> "Open {domain} to a partner's eye before the next sailing, and name {god} as witness."
            AspectType.SQUARE -> "Count {domain} twice today, and hand the tally to {god}'s clerk."
            AspectType.TRINE -> "Draw on {domain} today, and set aside {god}'s share."
            AspectType.OPPOSITION -> "Put {domain} on the table before noon, and let {god} set the price."
        }

        AncientCulture.ROME -> when (aspect) {
            AspectType.CONJUNCTION -> "Bring {domain} under one command today, and burn incense to {god}."
            AspectType.SEXTILE -> "Ask a friend in office for help with {domain}, and pour a libation to {god}."
            AspectType.SQUARE -> "Leave {domain} for tomorrow, and atone to {god} with a small offering."
            AspectType.TRINE -> "Push {domain} forward today, and hang a garland for {god} on the way."
            AspectType.OPPOSITION -> "Keep {domain} out of the vote today, and say the prayer to {god} once."
        }
    }

    /** Opens the second-figure sentence. */
    fun secondFigure(culture: AncientCulture): String = when (culture) {
        AncientCulture.EGYPT -> "Lower on the river,"
        AncientCulture.GREECE -> "At a lesser shrine,"
        AncientCulture.CANAAN -> "Further down the bench,"
        AncientCulture.CARTHAGE -> "Further down the page,"
        AncientCulture.ROME -> "Elsewhere in the sky,"
    }

    /** Stands in for the second figure when the sky offers none. */
    fun noSecondFigure(culture: AncientCulture): String = when (culture) {
        AncientCulture.EGYPT -> "Nothing else on the river comes near it, so this is the one thing you weigh today."
        AncientCulture.GREECE -> "No other shrine speaks today, so carry this one answer home."
        AncientCulture.CANAAN -> "No other matter reaches the floor today, so close this one before you leave."
        AncientCulture.CARTHAGE -> "Nothing else is entered today, so rule off under this line and go home."
        AncientCulture.ROME -> "The sky sends no second sign, so the rest of your day is yours to spend."
    }

    /** Closes the day page. */
    fun comeBack(culture: AncientCulture): String = when (culture) {
        AncientCulture.EGYPT -> "Come back at dawn, when the scale is set again."
        AncientCulture.GREECE -> "Bring your next question tomorrow, when the tripod is lit again."
        AncientCulture.CANAAN -> "The council sits again tomorrow, and your seat is kept."
        AncientCulture.CARTHAGE -> "Come back tomorrow, when the books open at first light."
        AncientCulture.ROME -> "The augur takes the auspices again at dawn, so come back tomorrow."
    }
}

/**
 * What each god brings before its institution: a short noun phrase in the
 * culture's own nouns. The week's ingress line reads it into its frame.
 */
fun deityCharge(culture: AncientCulture, body: Planet): String = when (culture) {
    AncientCulture.EGYPT -> when (body) {
        Planet.SUN -> "the day's own course"
        Planet.MOON -> "the count of the months"
        Planet.MERCURY -> "the storm off the red land"
        Planet.VENUS -> "the gathering of the limbs"
        Planet.MARS -> "the falcon's harpoon"
        Planet.JUPITER -> "the hidden king's hand"
        Planet.SATURN -> "the weight of the ground itself"
        Planet.URANUS -> "the gap of five days outside the year"
        Planet.NEPTUNE -> "the dark water under everything"
        Planet.PLUTO -> "the green grain of the Duat"
    }

    AncientCulture.GREECE -> when (body) {
        Planet.SUN -> "the eye that misses no deed"
        Planet.MOON -> "the light borrowed from Helios"
        Planet.MERCURY -> "the word carried through the door"
        Planet.VENUS -> "the girdle that turns every head"
        Planet.MARS -> "the slaughter looking for a field"
        Planet.JUPITER -> "the nod that shakes Olympus"
        Planet.SATURN -> "the sickle's one question"
        Planet.URANUS -> "the sky unthroned in one stroke"
        Planet.NEPTUNE -> "the ground that will not hold still"
        Planet.PLUTO -> "the silver under the earth"
    }

    AncientCulture.CANAAN -> when (body) {
        Planet.SUN -> "the herald's message brought down from the sky"
        Planet.MOON -> "the bride price paid by moonlight"
        Planet.MERCURY -> "the mace forged for Baal's hand"
        Planet.VENUS -> "the armed morning star"
        Planet.MARS -> "the arrow of plague in flight"
        Planet.JUPITER -> "the rain that decides the harvest"
        Planet.SATURN -> "the word from the tent at the source of the rivers"
        Planet.URANUS -> "the offering owed to Heaven itself"
        Planet.NEPTUNE -> "the sea's claim to the throne"
        Planet.PLUTO -> "the open gullet of death"
    }

    AncientCulture.CARTHAGE -> when (body) {
        Planet.SUN -> "the Tyrian sun over the new city"
        Planet.MOON -> "the dedication cut into the stele beneath the crescent"
        Planet.MERCURY -> "the guide's landfall on a foreign shore"
        Planet.VENUS -> "the war fleet launched under the Lady of the Sea"
        Planet.MARS -> "the champion's yearly tithe to Tyre"
        Planet.JUPITER -> "the horned lord of the gods"
        Planet.SATURN -> "the whole of the Ancient One's due"
        Planet.URANUS -> "the foremost name in the city's oath"
        Planet.NEPTUNE -> "the partner of every hull out of Carthage"
        Planet.PLUTO -> "the debt that outlives the debtor"
    }

    AncientCulture.ROME -> when (body) {
        Planet.SUN -> "the unconquered light"
        Planet.MOON -> "the chariot of the moon"
        Planet.MERCURY -> "the bargain struck in the market"
        Planet.VENUS -> "the marriage of two houses"
        Planet.MARS -> "the shield of the Salii"
        Planet.JUPITER -> "the thunderbolt from the Alban Mount"
        Planet.SATURN -> "the treasury at the Capitol's foot"
        Planet.URANUS -> "the canopy over every army"
        Planet.NEPTUNE -> "the failing spring at the Neptunalia"
        Planet.PLUTO -> "the altar buried at the Tarentum"
    }
}

/** The verb an ingress line uses: "{deity} {verb} the {sign image}." */
fun ingressVerb(culture: AncientCulture): String = when (culture) {
    AncientCulture.EGYPT -> "is ferried into"
    AncientCulture.GREECE -> "goes on to the shrine of"
    AncientCulture.CANAAN -> "comes before"
    AncientCulture.CARTHAGE -> "makes port in"
    AncientCulture.ROME -> "enters the augur's boundary of"
}

/**
 * The ruling on an ingress, taking the moving body's charge. A body that has
 * crossed into a new sign has not been ruled on there yet, and each of these
 * says that in its own institution's terms.
 */
fun ingressFrame(culture: AncientCulture, c: String): String = when (culture) {
    AncientCulture.EGYPT -> "The priest of the hours on the temple roof watches the sign's decans rise and reads ${c} in them."
    AncientCulture.GREECE -> "The priests there begin the sacrifice for ${c}."
    AncientCulture.CANAAN -> "${cap(c)} moves to the house of another god, where no envoy has announced it."
    AncientCulture.CARTHAGE -> "The clerk carries ${c} onto a fresh sheet of the ledger and rules off the last one."
    AncientCulture.ROME -> "The auspices taken for ${c} lapse at that boundary, and the college takes new ones beyond it."
}
